function getSvg(comment_total) {
   const {java} = this;
let svg = `
  <svg width="1000" height="800" xmlns="http://www.w3.org/2000/svg">
    <path d="M865 100 h-600c-60 0-110 50-110 110v150l-120 80 120 80v150c0 60 50 110 110 110h600c60 0 110-50 110-110V210c0-60-50-110-110-110z  " fill="none" stroke="#B2B2B2" stroke-width="55"/>
    <text x="570" y="565" font-family="Roboto Condensed" text-anchor="middle" dominant-baseline="middle" font-size="420" font-weight="bold" fill="#707070">
